package config

import (
	"io/ioutil"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestScheme(t *testing.T) {
	tests := []struct {
		name   string
		scheme Scheme
		want   string
	}{
		{
			name:   "https",
			scheme: HTTPS,
			want:   "https",
		},
		{
			name:   "http",
			scheme: HTTP,
			want:   "http",
		},
	}

	for _, tt := range tests {
		var (
			scheme = tt.scheme
			want   = tt.want
		)

		t.Run(tt.name, func(t *testing.T) {
			assert.Equal(t, want, scheme.String())
		})
	}
}

func TestLoad(t *testing.T) {
	tests := []struct {
		name     string
		path     string
		wantErr  bool
		expected *Config
	}{
		{
			name:     "defaults",
			path:     "./testdata/config/default.yml",
			expected: Default(),
		},
		{
			name:     "deprecated defaults",
			path:     "./testdata/config/deprecated.yml",
			expected: Default(),
		},
		{
			name: "updates enabled",
			path: "./testdata/config/updates.yml",
			expected: func() *Config {
				cfg := Default()
				cfg.Meta.CheckForUpdates = true
				return cfg
			}(),
		},
		{
			name: "configured",
			path: "./testdata/config/advanced.yml",
			expected: &Config{
				Log: logConfig{
					Level: "WARN",
					File:  "testLogFile.txt",
				},
				UI: uiConfig{
					Enabled: false,
				},
				Cors: corsConfig{
					Enabled:        true,
					AllowedOrigins: []string{"foo.com"},
				},
				Cache: cacheConfig{
					Memory: memoryCacheConfig{
						Enabled:          true,
						Expiration:       5 * time.Minute,
						EvictionInterval: 1 * time.Minute,
					},
				},
				Server: serverConfig{
					Host:      "127.0.0.1",
					Protocol:  HTTPS,
					HTTPPort:  8081,
					HTTPSPort: 8080,
					GRPCPort:  9001,
					CertFile:  "./testdata/config/ssl_cert.pem",
					CertKey:   "./testdata/config/ssl_key.pem",
				},
				Database: databaseConfig{
					MigrationsPath:  "./config/migrations",
					URL:             "postgres://postgres@localhost:5432/flipt?sslmode=disable",
					MaxIdleConn:     5,
					MaxOpenConn:     20,
					ConnMaxLifetime: 30 * time.Minute,
				},
				Meta: metaConfig{
					CheckForUpdates: false,
				},
			},
		},
	}

	for _, tt := range tests {
		var (
			path     = tt.path
			wantErr  = tt.wantErr
			expected = tt.expected
		)

		t.Run(tt.name, func(t *testing.T) {
			cfg, err := Load(path)

			if wantErr {
				require.Error(t, err)
				return
			}

			require.NoError(t, err)

			assert.NotNil(t, cfg)
			assert.Equal(t, expected, cfg)
		})
	}
}

func TestValidate(t *testing.T) {
	tests := []struct {
		name       string
		cfg        *Config
		wantErr    bool
		wantErrMsg string
	}{
		{
			name: "https: valid",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/config/ssl_cert.pem",
					CertKey:  "./testdata/config/ssl_key.pem",
				},
			},
		},
		{
			name: "http: valid",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTP,
					CertFile: "foo.pem",
					CertKey:  "bar.pem",
				},
			},
		},
		{
			name: "https: empty cert_file path",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "",
					CertKey:  "./testdata/config/ssl_key.pem",
				},
			},
			wantErr:    true,
			wantErrMsg: "cert_file cannot be empty when using HTTPS",
		},
		{
			name: "https: empty key_file path",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/config/ssl_cert.pem",
					CertKey:  "",
				},
			},
			wantErr:    true,
			wantErrMsg: "cert_key cannot be empty when using HTTPS",
		},
		{
			name: "https: missing cert_file",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "foo.pem",
					CertKey:  "./testdata/config/ssl_key.pem",
				},
			},
			wantErr:    true,
			wantErrMsg: "cannot find TLS cert_file at \"foo.pem\"",
		},
		{
			name: "https: missing key_file",
			cfg: &Config{
				Server: serverConfig{
					Protocol: HTTPS,
					CertFile: "./testdata/config/ssl_cert.pem",
					CertKey:  "bar.pem",
				},
			},
			wantErr:    true,
			wantErrMsg: "cannot find TLS cert_key at \"bar.pem\"",
		},
	}

	for _, tt := range tests {
		var (
			cfg        = tt.cfg
			wantErr    = tt.wantErr
			wantErrMsg = tt.wantErrMsg
		)

		t.Run(tt.name, func(t *testing.T) {
			err := cfg.validate()

			if wantErr {
				require.Error(t, err)
				assert.EqualError(t, err, wantErrMsg)
				return
			}

			require.NoError(t, err)
		})
	}
}

func TestServeHTTP(t *testing.T) {
	var (
		cfg = Default()
		req = httptest.NewRequest("GET", "http://example.com/foo", nil)
		w   = httptest.NewRecorder()
	// DB
	if viper.IsSet(cfgDBURL) {
		cfg.Database.URL = viper.GetString(cfgDBURL)
	}

	if viper.IsSet(cfgDBMigrationsPath) {
		cfg.Database.MigrationsPath = viper.GetString(cfgDBMigrationsPath)
	}

	if viper.IsSet(cfgDBMaxIdleConn) {
		cfg.Database.MaxIdleConn = viper.GetInt(cfgDBMaxIdleConn)
	}

	if viper.IsSet(cfgDBMaxOpenConn) {
		cfg.Database.MaxOpenConn = viper.GetInt(cfgDBMaxOpenConn)
	}

	if viper.IsSet(cfgDBConnMaxLifetime) {
		cfg.Database.ConnMaxLifetime = viper.GetDuration(cfgDBConnMaxLifetime)
	}

	// Meta
	if viper.IsSet(cfgMetaCheckForUpdates) {
		cfg.Meta.CheckForUpdates = viper.GetBool(cfgMetaCheckForUpdates)
	}

	if err := cfg.validate(); err != nil {
		return &Config{}, err
	}

	return cfg, nil
}

func (c *Config) validate() error {
	if c.Server.Protocol == HTTPS {
		if c.Server.CertFile == "" {
			return errors.New("cert_file cannot be empty when using HTTPS")
		}

		if c.Server.CertKey == "" {
			return errors.New("cert_key cannot be empty when using HTTPS")
		}

		if _, err := os.Stat(c.Server.CertFile); os.IsNotExist(err) {
			return fmt.Errorf("cannot find TLS cert_file at %q", c.Server.CertFile)
		}

		if _, err := os.Stat(c.Server.CertKey); os.IsNotExist(err) {
			return fmt.Errorf("cannot find TLS cert_key at %q", c.Server.CertKey)
		}
	}

	return nil
}

func (c *Config) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	out, err := json.Marshal(c)
	if err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		return
	}

	if _, err = w.Write(out); err != nil {
		w.WriteHeader(http.StatusInternalServerError)
		return
	}
}

